create temporary table profile_scope_checks(label text primary key);
do $$
declare a uuid:=gen_random_uuid();m uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();x uuid:=gen_random_uuid();p uuid:=gen_random_uuid();i uuid:=gen_random_uuid();ix uuid:=gen_random_uuid();failed boolean;result jsonb;
begin
 insert into auth.users(id,email) select id,'qa-scope-'||id||'@example.invalid' from unnest(array[a,m,u,v,x]) id;
 insert into public.profiles(id,email,role,status,permissions) values(a,'qa-scope-'||a||'@example.invalid','super_admin','active','{}'),(m,'qa-scope-'||m||'@example.invalid','manager','active','{"sales_inventory":["read","intake","assign_inhouse"],"sales_operations":["manage_payout","read_reports_all","verify_reports"]}'),(u,'qa-scope-'||u||'@example.invalid','operator','active','{"sales_inventory":["intake"],"sales_operations":["read_reports_all"]}'),(v,'qa-scope-'||v||'@example.invalid','viewer','active','{}'),(x,'qa-scope-'||x||'@example.invalid','operator','active','{"sales_inventory":["intake"]}');
 insert into public.user_reporting_lines(employee_user_id,manager_user_id,status,created_by) values(u,m,'active',a),(v,u,'active',a);
 insert into public.pages(id,name,meta_connection,registry_source,updated_at) select id,'QA scope '||id,'sales_inventory','sales_inventory',now() from unnest(array['990019233000','990019233001','990019233002','990019233003']) id;
 insert into public.page_assignments(page_id,user_id,status,assignment_role) values('990019233000',m,'active','manager'),('990019233001',u,'active','operator'),('990019233002',v,'active','operator'),('990019233003',x,'active','operator');
 if not public.operations_page_visible(a,'990019233003') or not public.operations_page_visible(a,'990019233001') then raise exception 'QA admin scope';end if;insert into profile_scope_checks values('administrator sees all Pages');
 if not public.operations_page_visible(m,'990019233000') or not public.operations_page_visible(m,'990019233001') or not public.operations_page_visible(m,'990019233002') or public.operations_page_visible(m,'990019233003') then raise exception 'QA manager scope';end if;insert into profile_scope_checks values('manager sees own direct and indirect branch only');
 if not public.operations_page_visible(u,'990019233001') or public.operations_page_visible(u,'990019233002') or public.operations_page_visible(v,'990019233001') then raise exception 'QA staff inherited scope';end if;insert into profile_scope_checks values('staff and contributor see direct Pages only despite reporting lines');
 insert into public.sales_products(id,sku,name,unit_price_vnd,status,product_group) values(p,'QA-SCOPE-'||p,'QA scope',100000,'active','fanpage');
 insert into public.sales_inventory_items(id,product_id,inventory_code,status,created_by) values(i,p,'QA-SCOPE-'||i,'inhouse_transferred',a),(ix,p,'QA-SCOPE-'||ix,'inhouse_transferred',a);
 insert into public.fanpage_inventory_details(inventory_item_id,facebook_page_id,page_name,page_link) values(i,'990019233001','QA original','https://facebook.com/990019233001'),(ix,'990019233003','QA outside','https://facebook.com/990019233003');
 insert into public.inhouse_page_inventory(inventory_item_id,page_id,status,transferred_by) values(i,'990019233001','active',a),(ix,'990019233003','active',a);
 if not public.operations_inventory_visible(m,i) or public.operations_inventory_visible(m,ix) or public.operations_inventory_visible(v,i) then raise exception 'QA inventory scope';end if;insert into profile_scope_checks values('inventory follows Page branch scope');
 result:=public.operations_account_assets(m);if result->>'source'<>'inhouse_current' or jsonb_array_length(result->'page_ids')<>1 or not(result->'page_ids' ? '990019233001') or result->'page_ids' ? '990019233000' then raise exception 'QA account includes legacy Page data';end if;insert into profile_scope_checks values('account counts current Inhouse only and excludes old Page grants');
 perform public.sales_inventory_rename_page(m,jsonb_build_object('inventory_item_id',i,'page_name','QA renamed'));if not exists(select 1 from public.pages where id='990019233001' and name='QA renamed') or not exists(select 1 from public.fanpage_inventory_details where inventory_item_id=i and page_name='QA renamed') then raise exception 'QA internal rename inconsistent';end if;insert into profile_scope_checks values('rename updates inventory and registry together');
 failed:=false;begin perform public.sales_inventory_rename_page(x,jsonb_build_object('inventory_item_id',i,'page_name','Forbidden'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA foreign rename';end if;insert into profile_scope_checks values('intake permission does not bypass Page scope');
 failed:=false;begin perform public.inhouse_payout_save(m,jsonb_build_object('page_id','990019233003','external_id','QA foreign'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA foreign payout';end if;insert into profile_scope_checks values('payout permission does not bypass Page scope');
 result:=public.profile_contacts_save(u,'{"phone":"0900000000","facebook_profile_url":"https://www.facebook.com/qa.profile"}');if result->'profile'->>'role'<>'operator' or result->'profile'->>'phone'<>'0900000000' then raise exception 'QA contact save';end if;insert into profile_scope_checks values('contact save preserves role and permissions');
 failed:=false;begin perform public.profile_contacts_save(u,'{"role":"super_admin"}');exception when raise_exception then if sqlerrm='Invalid contact fields' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA privilege escalation';end if;insert into profile_scope_checks values('contact RPC rejects authorization fields');
 failed:=false;begin perform public.profile_contacts_save(u,'{"facebook_profile_url":"javascript:alert(1)"}');exception when raise_exception then if sqlerrm='Invalid Facebook profile' then failed:=true;else raise;end if;end;if not failed or (select facebook_profile_url from public.profiles where id=u)<>'https://www.facebook.com/qa.profile' then raise exception 'QA invalid URL altered profile';end if;insert into profile_scope_checks values('invalid Facebook URL rejected without changing profile');
 if has_function_privilege('authenticated','public.profile_contacts_save(uuid,jsonb)','execute') or has_function_privilege('authenticated','public.operations_visible_pages(uuid)','execute') then raise exception 'QA public execute';end if;insert into profile_scope_checks values('client cannot call privileged RPCs');
end $$;
select label as passed from profile_scope_checks order by label;
